--- a/internal/band/skip.go
+++ b/internal/band/skip.go
@@
+// SkipClass returns the class token a skip marker names.
+func SkipClass(marker string) (string, bool) {
+	const pfx = "skipped:"
+	if !strings.HasPrefix(marker, pfx) || len(marker) == len(pfx) {
+		return "", false
+	}
+	return marker[len(pfx):], true
+}

--- a/internal/harvest/metrics.go
+++ b/internal/harvest/metrics.go
@@
+func (m Metrics) Coverage() float64 {
+	if m.Universe == 0 {
+		return 0
+	}
+	return float64(m.Reviewed) / float64(m.Universe)
+}

--- a/internal/floor/compose.go
+++ b/internal/floor/compose.go
@@
+func Compose(a, b Screener) Screener {
+	if a == nil || b == nil {
+		panic("floor.Compose: nil screener")
+	}
+	return composite{a: a, b: b}
+}
